package net.atlasauth.pca;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/**
 * 0.5 mutation kills for {@link Ledger}: a differential test against the TS reference (the shared k05 oracle,
 * test-data/k05-ledger.json.gz, generated by tools/pca-audit/k05-oracles/ledger-oracle.mts) through the short (pin-less)
 * overloads, plus the inputs the reference cannot produce: a signature over the body of a head that lacks a member, and a
 * proof object that fails while it is read.
 */
public class K05LedgerDiffTest {
    static final String MODULE = "k05-ledger";

    @SuppressWarnings("unchecked") static Map<String, Object> m(Object o) { return (Map<String, Object>) o; }
    static Map<String, Object> mapOrNull(Object o) { return o instanceof Map ? m(o) : null; }

    interface Fn { Object apply(List<?> a) throws Exception; }

    static void each(String fn, Fn f) throws Exception {
        List<Map<String, Object>> cases = K05Oracle.of(MODULE, fn);
        assertFalse(cases.isEmpty(), "no oracle cases for " + fn);
        List<String> bad = new ArrayList<>();
        for (Map<String, Object> c : cases) {
            Object want = c.get("out"), got = null;
            Throwable err = null;
            try { got = f.apply((List<?>) c.get("args")); } catch (Throwable t) { err = t; }
            if (err != null) bad.add(c.get("name") + "\n  want: " + want + "\n  got:  THROWS " + err);
            else if (!IntentJs.jsonEquals(want, got)) bad.add(c.get("name") + "\n  want: " + want + "\n  got:  " + got);
        }
        assertTrue(bad.isEmpty(), bad.size() + " of " + cases.size() + " divergent case(s):\n" + String.join("\n", bad.subList(0, Math.min(bad.size(), 40))));
    }

    @Test void consistency() throws Exception { each("verifyLedgerConsistency", a -> Ledger.verifyLedgerConsistency(a.get(0), a.get(1), a.get(2))); }

    @Test void inclusion() throws Exception { each("verifyLedgerInclusion", a -> Ledger.verifyLedgerInclusion((String) a.get(0), a.get(1), a.get(2))); }

    @Test void witnessedHeads() throws Exception {
        each("verifyWitnessedHead", a -> Ledger.verifyWitnessedHead(a.get(0), (String) a.get(1)));
        each("detectEquivocation", a -> Ledger.detectEquivocation(a.get(0), a.get(1), (String) a.get(2)));
    }

    @Test void cosignatures() throws Exception {
        each("verifyWitnessCosignature", a -> Ledger.verifyWitnessCosignature(a.get(0), a.get(1), (String) a.get(2)));
        each("verifyWitnessCosignatures", a -> Ledger.verifyWitnessCosignatures(a.get(0), mapOrNull(a.get(1))));
    }

    @Test void treeHeads() throws Exception {
        each("verifyTreeHead", a -> Ledger.verifyTreeHead(a.get(0), (String) a.get(1), mapOrNull(a.get(2))));
        each("verifyHeadConsistency", a -> Ledger.verifyHeadConsistency(a.get(0), a.get(1), a.get(2), (String) a.get(3), mapOrNull(a.get(4))));
    }

    @Test void checkpointChains() throws Exception {
        each("verifyCheckpointChain", a -> {
            Ledger.CheckpointVerdict v = Ledger.verifyCheckpointChain(a.get(0), (String) a.get(1), mapOrNull(a.get(2)));
            Map<String, Object> out = new LinkedHashMap<>();
            out.put("ok", v.ok);
            if (!v.ok) out.put("at", (long) v.at);
            else if (v.at != 0) throw new AssertionError("an ok verdict carries at = 0");
            return out;
        });
        assertEquals("CheckpointVerdict{ok=false, at=3}", new Ledger.CheckpointVerdict(false, 3).toString());
    }

    static byte[] seed(int fill) {
        byte[] b = new byte[32];
        java.util.Arrays.fill(b, (byte) fill);
        return b;
    }

    /** A signature over domain || "null": what a verifier would check if it signed a missing body as JSON null. */
    static String sigOverNull(int fill, String domain) {
        return Keys.b64u(Keys.edFromSeed(seed(fill)).sign((domain + "null").getBytes(StandardCharsets.UTF_8)));
    }

    @Test void aHeadWithoutAMemberNeverVerifies() {
        String w1 = Keys.edFromSeed(seed(102)).id(), guardian = Keys.edFromSeed(seed(101)).id();
        Map<String, Object> wh = new LinkedHashMap<>();
        wh.put("principal", "alice");
        wh.put("size", 5L);
        wh.put("witness", w1);
        wh.put("sig", sigOverNull(102, Ledger.LEDGER_HEAD_DOMAIN));
        assertFalse(Ledger.verifyWitnessedHead(wh, w1), "no root");
        Map<String, Object> sth = new LinkedHashMap<>();
        sth.put("instance_id", "ins1");
        sth.put("principal", "alice");
        sth.put("size", 5L);
        sth.put("root", Ledger.EMPTY_TREE_ROOT);
        sth.put("timestamp", 1L);
        sth.put("guardian", guardian);
        sth.put("sig", sigOverNull(101, Ledger.STH_DOMAIN));
        assertFalse(Ledger.verifyTreeHead(sth, guardian, null), "no prev_root");
        Map<String, Object> cosig = new LinkedHashMap<>();
        cosig.put("key", w1);
        cosig.put("sig", sigOverNull(102, Ledger.STH_WITNESS_DOMAIN));
        assertFalse(Ledger.verifyWitnessCosignature(sth, cosig, w1), "no prev_root");
    }

    static byte[] filled(int b) {
        byte[] out = new byte[32];
        java.util.Arrays.fill(out, (byte) b);
        return out;
    }

    static Map<String, Object> proof(long oldSize, long newSize, byte[]... path) {
        List<Object> p = new ArrayList<>();
        for (byte[] h : path) p.add(Pca.b64(h));
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("oldSize", oldSize);
        out.put("newSize", newSize);
        out.put("path", p);
        return out;
    }

    /**
     * Sizes out of order (a negative old size, an old size above the new one) with a path and roots chosen so the hashing
     * walk itself would end at both roots: only the order check refuses them.
     */
    @Test void sizesOutOfOrderNeverVerifyEvenWhenThePathWalksToBothRoots() {
        byte[] p0 = filled(1), c1 = filled(2), c2 = filled(3);
        // oldSize -1, newSize 2: the walk ends with fr = p0, sr = H(p0, c1)
        assertFalse(Ledger.verifyLedgerConsistency(Pca.b64(p0), Pca.b64(Pca.nodeHash(p0, c1)), proof(-1, 2, p0, c1)));
        // oldSize 7 > newSize 3: the walk ends with fr = H(c2, p0), sr = H(c2, H(p0, c1))
        assertFalse(Ledger.verifyLedgerConsistency(Pca.b64(Pca.nodeHash(c2, p0)), Pca.b64(Pca.nodeHash(c2, Pca.nodeHash(p0, c1))), proof(7, 3, p0, c1, c2)));
    }

    /** A proof whose members fail on read: the verifier answers false, it never throws. */
    @Test void consistencyNeverThrows() {
        Map<String, Object> boom = new LinkedHashMap<String, Object>() {
            @Override public Object get(Object k) { throw new IllegalStateException("read failed"); }
        };
        assertFalse(Ledger.verifyLedgerConsistency(Ledger.EMPTY_TREE_ROOT, Ledger.EMPTY_TREE_ROOT, boom));
    }

    /** A consistency node that is not 32 bytes never starts or feeds the walk (old size 1: the old root is the start). */
    @Test
    void consistencyRefusesNodesThatAreNot32Bytes() throws Exception {
        byte[] c = new byte[32];
        for (int i = 0; i < 32; i++) c[i] = (byte) (i * 7 + 1);
        for (int len : new int[] {31, 32, 33}) {
            byte[] bad = new byte[len];
            for (int i = 0; i < len; i++) bad[i] = (byte) (i * 3 + 5);
            Map<String, Object> proof = new LinkedHashMap<>();
            proof.put("oldSize", 1.0);
            proof.put("newSize", 2.0);
            proof.put("path", List.of(Pca.b64(c)));
            boolean forged = Ledger.verifyLedgerConsistency(Pca.b64(bad), Pca.b64(Pca.nodeHash(bad, c)), proof);
            Map<String, Object> proof2 = new LinkedHashMap<>(proof);
            proof2.put("path", List.of(Pca.b64(bad)));
            boolean forged2 = Ledger.verifyLedgerConsistency(Pca.b64(c), Pca.b64(Pca.nodeHash(c, bad)), proof2);
            assertEquals(len == 32, forged, "old root of " + len + " bytes");
            assertEquals(len == 32, forged2, "path node of " + len + " bytes");
        }
    }
}
